    <script>
        const eyeIcon = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M2.5 12s3.5-6 9.5-6 9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z"/><circle cx="12" cy="12" r="2.5"/><path class="eye-slash" d="m4 4 16 16"/></svg>';
        document.querySelectorAll('[data-toggle]').forEach(button => { button.innerHTML = eyeIcon; button.setAttribute('aria-pressed', 'false'); button.addEventListener('click', () => { const input=document.getElementById(button.dataset.toggle), visible=input.type==='text'; input.type=visible?'password':'text'; button.classList.toggle('is-visible', !visible); button.setAttribute('aria-label',visible?'Show password':'Hide password'); button.setAttribute('aria-pressed', String(!visible)); }); });
        const passwordInput=document.querySelector('#password'), confirmationInput=document.querySelector('#password_confirmation'), matchMessage=document.querySelector('#password-match');
        function updatePasswordMatch(){const hasConfirmation=confirmationInput.value.length>0, matches=hasConfirmation&&passwordInput.value===confirmationInput.value; matchMessage.className='password-match'+(hasConfirmation?' is-visible '+(matches?'is-match':'is-mismatch'):'' ); matchMessage.textContent=hasConfirmation?(matches?'✓ Passwords match.':'Passwords do not match.') : '';}
        passwordInput?.addEventListener('input', function () { const value=this.value, score=[value.length>=8,value.length>=12,/[a-z]/.test(value)&&/[A-Z]/.test(value),/\d/.test(value),/[^A-Za-z0-9]/.test(value)].filter(Boolean).length, bar=document.querySelector('#password-strength'), help=document.querySelector('#password-help'), labels=['Weak password','Weak password','Fair password','Strong password','Strong password'], colors=['#fb7185','#fb7185','#f59e0b','#10b981','#10b981']; bar.style.width=(score*20)+'%'; bar.style.background=colors[Math.max(0,score-1)]; help.textContent=value?labels[Math.max(0,score-1)]:'Use 8+ characters with upper/lowercase, a number, and a symbol.'; updatePasswordMatch(); });
        confirmationInput?.addEventListener('input', updatePasswordMatch);
        document.querySelector('#credentialSetupForm')?.addEventListener('submit', function () { if(this.checkValidity()){const button=document.querySelector('#saveCredentialsButton');button.classList.add('is-loading');button.disabled=true;} });
    </script>
